```python
import random

def brute(xs, target):
    for i in range(len(xs)):
        for j in range(i + 1, len(xs)):
            if xs[i] + xs[j] == target:
                return True
    return False

def check(optimized, trials=1000):
    for _ in range(trials):
        xs = [random.randint(-10, 10) for _ in range(random.randint(0, 8))]
        t = random.randint(-20, 20)
        if brute(xs, t) != optimized(xs, t):
            return xs, t
    return None
```

Swap in your own brute function and optimized function. `check` returns the first failing input or None.

